// ── azy.daily#645 — rendre l'échec LISIBLE, au lieu d'un 200 à corps vide ────
//
// Avant : les nœuds *ToolDynamic levaient, le workflow mourait avant son
// `respondToWebhook`, et n8n fermait la requête en HTTP 200 SANS CORPS. Trois
// causes très différentes produisaient ce même vide, et aucun appelant ne pouvait
// les distinguer d'une boîte réellement vide :
//     route morte · refus d'autorisation de Google · paire resource/operation non routée
// MCP le dit explicitement : son `_normalize_response` traduisait ce vide en
// `success=True, data=[]`, c'est-à-dire « boîte vide ».
//
// Maintenant : les nœuds portent `onError: continueRegularOutput`, donc leur
// erreur ARRIVE ICI comme une donnée, et ce nœud la qualifie.
//
// ⚠️ `JSON.stringify` LAISSE TOMBER les clés `undefined` (n8n-workflows#467, c'est
// ainsi que GUILD - Server Sync avait perdu son champ `success`). Chaque clé est
// donc posée explicitement, jamais laissée indéfinie.

const entree = $input.first().json || {};

const enveloppe = (code, message, statut, detail) => ({
  success: false,
  data: null,
  // ⚠️ Le code est publié DEUX FOIS, volontairement. MCP lit un `error_code` À PLAT
  // dans le corps (`_normalize_response`) ; le publier aussi à la racine leur évite
  // toute adaptation et fait remonter nos codes stables au lieu d'un générique.
  // Les deux valeurs viennent de la MÊME variable : elles ne peuvent pas diverger.
  error_code: code,
  error: {
    code: code,                       // stable, fait pour être testé par l'appelant
    message: String(message || 'Erreur inconnue'),
    http_status: statut,
  },
  _trace: {
    http_status: statut,
    noeud: String(detail || ''),
  },
});

// 1 · Paire resource/operation non routée (vient du nœud `Route inconnue`).
if (entree._route_inconnue === true) {
  return enveloppe(
    'TOOL_ROUTE_UNKNOWN',
    entree._message || 'Paire resource/operation non routée par ce serveur',
    400,
    'Route by Resource + Operation');
}

// 2 · Le nœud a échoué et nous a transmis son erreur.
const brut = String(entree.error || '');
if (brut) {
  // ⚠️ L'ordre compte : « Unknown … operation » doit être reconnu AVANT les codes
  // HTTP, car il ne porte aucun statut — c'est un défaut de CÂBLAGE chez nous, pas
  // un refus de Google. Le confondre avec une erreur d'API ferait chercher la
  // panne du mauvais côté.
  if (/Unknown\s+\w+\s+operation/i.test(brut)) {
    return enveloppe('TOOL_OPERATION_UNKNOWN', brut, 501, 'nœud dynamique');
  }
  if (/Authorization failed/i.test(brut) || /\b40[13]\b/.test(brut)) {
    return enveloppe('GOOGLE_AUTH_REJECTED',
                     'Google a refusé le jeton fourni dans le corps de la requête',
                     401, 'nœud dynamique');
  }
  if (/\b404\b/.test(brut) || /not found/i.test(brut)) {
    return enveloppe('GOOGLE_NOT_FOUND', brut, 404, 'nœud dynamique');
  }
  if (/\b429\b/.test(brut) || /rate limit/i.test(brut) || /quota/i.test(brut)) {
    return enveloppe('GOOGLE_RATE_LIMITED', brut, 429, 'nœud dynamique');
  }
  return enveloppe('GOOGLE_API_ERROR', brut, 502, 'nœud dynamique');
}

// 3 · Succès. `data` porte la réponse de Google telle quelle — on n'enlève et on
// n'ajoute rien : c'est ce qui permet de comparer le direct et le via-n8n.
// ⚠️ SUR SUCCÈS, NI `error` NI `error_code` NE SONT POSÉS — ET C'EST VOULU.
//
// J'avais d'abord choisi la forme stable (`error: null`, `error_code: null`
// toujours présents), en me disant qu'un appelant testant `'error_code' in corps`
// conclurait au hasard. MCP a mesuré l'inverse chez lui : son `_normalize_response`
// discrimine sur la PRÉSENCE de la clé (`"error" in data or "error_code" in data`),
// et `client.py` lui passe l'enveloppe entière sans la déballer. Une enveloppe de
// succès portant `error: null` serait donc classée en ERREUR.
//
// Les clés absentes satisfont les DEUX styles de détection : la présence (absent
// = succès) comme la valeur (`if (corps.error)` → faux). La forme stable n'en
// satisfaisait qu'un. Omettre est donc le choix dominant, et il dispense MCP de
// durcir quoi que ce soit avant notre réimport.
//
// Le signal positif reste explicite : `success: true` et `_trace.http_status: 200`.
return {
  success: true,
  data: entree,
  _trace: { http_status: 200, noeud: '' },
};

// ── azy.daily#645 — la troisième cause du « 200 vide » ───────────────────────
//
// Le `Switch` portait `fallbackOutput: none` : une paire resource/operation qu'il
// ne connaît pas ne produisait AUCUNE sortie, le workflow se terminait sans rien,
// et n8n fermait en 200 vide. Il porte maintenant une sortie de repli, câblée ici.
//
// Ce chemin est loin d'être théorique : la route backend-to-backend de MCP
// (`POST /api/tools/{tool_id}/execute`) relaie `operation` VERBATIM, sans le
// valider contre les opérations gérées. N'importe quelle valeur peut donc arriver.
//
// ⚠️ On n'écho PAS le corps reçu : il contient le jeton OAuth. Seuls `resource` et
// `operation` sont repris, et rien d'autre.
const corps = ($input.first().json || {}).body || {};
return {
  _route_inconnue: true,
  _message: 'Paire non routée par ce serveur : resource=' +
            JSON.stringify(corps.resource === undefined ? null : corps.resource) +
            ', operation=' +
            JSON.stringify(corps.operation === undefined ? null : corps.operation),
};
